export const COPILOT_HTML = "<!doctype html>\n<html lang=\"en\"><head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#090b0f\"><meta name=\"description\" content=\"AskMoina Live Co-Pilot — real-time voice guidance with a full-screen camera view.\">\n<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'none'; form-action 'self'; connect-src 'self' wss:; img-src 'self' data: blob:; style-src 'self'; script-src 'self'; media-src 'self' blob:\">\n<title>Live Co-Pilot · AskMoina</title><link rel=\"stylesheet\" href=\"/copilot.css\"><script src=\"/transcript-merge.js\" defer></script><script src=\"/copilot.js\" defer></script></head>\n<body><main class=\"camera-app\" aria-label=\"AskMoina live camera co-pilot\"><section class=\"camera-stage\" id=\"cameraStage\" aria-label=\"Live camera view\">\n<video id=\"videoPreview\" autoplay playsinline muted aria-label=\"Live camera preview\"></video>\n<div class=\"camera-placeholder\" id=\"cameraPlaceholder\"><div class=\"camera-placeholder-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 48 48\" role=\"presentation\"><rect x=\"5\" y=\"12\" width=\"28\" height=\"24\" rx=\"5\"></rect><path d=\"M33 20l10-6v20l-10-6z\"></path><circle cx=\"19\" cy=\"24\" r=\"6\"></circle></svg></div><strong>Point. Ask. Follow.</strong><span>Tap Start to show Moina what you see.</span></div>\n<header class=\"floating-top\"><a class=\"brand\" href=\"/\" aria-label=\"AskMoina home\"><span class=\"brand-mark\" aria-hidden=\"true\">m</span><span>Moina</span></a><span class=\"vision-pill\"><span class=\"live-dot\"></span> LIVE VISION</span></header>\n<div class=\"camera-top-badge\" id=\"frameBadge\"><span class=\"live-dot\"></span> WAITING FOR CAMERA</div><span class=\"camera-state\" id=\"cameraState\"><span class=\"state-dot\"></span> Camera paused</span>\n<div class=\"focus-marker\" id=\"focusMarker\" data-region=\"center\" hidden><div class=\"focus-brackets\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></div><div class=\"focus-card\"><span class=\"focus-eyebrow\">MOINA'S FOCUS</span><strong id=\"focusLabel\">Target</strong><span class=\"focus-hint\" id=\"focusHint\"></span><p id=\"focusInstruction\"></p></div><button type=\"button\" id=\"clearMarker\" class=\"clear-marker\" aria-label=\"Clear focus marker\">×</button></div>\n<div class=\"approx-tag\" id=\"approxTag\" hidden>Approximate focus · not world-locked AR</div>\n<div class=\"zoom-dock\" aria-label=\"Camera zoom controls\"><button type=\"button\" id=\"zoomOut\" aria-label=\"Zoom out\" disabled>−</button><label class=\"sr-only\" for=\"zoomSlider\">Camera zoom</label><input id=\"zoomSlider\" type=\"range\" min=\"1\" max=\"3\" step=\"0.1\" value=\"1\" aria-label=\"Camera zoom\" disabled><output id=\"zoomLabel\" for=\"zoomSlider\">1×</output><button type=\"button\" id=\"zoomIn\" aria-label=\"Zoom in\" disabled>+</button></div>\n<section class=\"caption-dock\" aria-label=\"Live conversation\"><div class=\"status-line\"><span class=\"assistant-orb\" aria-hidden=\"true\">m</span><div class=\"status-copy\"><strong id=\"connectionPill\" data-state=\"ready\">READY</strong><p id=\"status\" role=\"status\" aria-live=\"polite\">Checking the voice service…</p></div><button type=\"button\" id=\"toggleCaptions\" class=\"caption-toggle\" aria-label=\"Show conversation captions\" aria-controls=\"transcript\" aria-expanded=\"false\">CC</button><span id=\"availability\" class=\"availability\" role=\"status\" aria-live=\"polite\">Checking capacity…</span></div><div class=\"transcript\" id=\"transcript\" role=\"log\" aria-live=\"polite\" aria-relevant=\"additions text\"><div class=\"empty-state\" id=\"emptyTranscript\"><p>Ask about what’s in front of you.</p></div></div><button type=\"button\" id=\"clearTranscript\" class=\"clear-captions\">Clear captions</button></section>\n<nav class=\"camera-controls\" aria-label=\"Camera and voice controls\">\n  <div class=\"secondary-controls\" id=\"secondaryControls\" hidden>\n    <button type=\"button\" id=\"flipCamera\" class=\"control-pill\" disabled><span aria-hidden=\"true\">↻</span> Flip camera</button>\n    <button type=\"button\" id=\"muteMic\" class=\"control-pill\" disabled><span aria-hidden=\"true\">♩</span> Mute</button>\n    <button type=\"button\" id=\"spatialArButton\" class=\"control-pill spatial-ar-button\" hidden disabled title=\"Open the guided AR view on supported devices\"><span aria-hidden=\"true\">◎</span> AR Guide</button>\n    <a class=\"control-pill secondary-link\" href=\"/vault\" aria-label=\"Open Memory Vault\">Memory Vault</a>\n  </div>\n  <div class=\"primary-control-row\">\n    <button type=\"button\" id=\"toggleMoreControls\" class=\"control-pill more-control\" aria-label=\"More controls\" aria-controls=\"secondaryControls\" aria-expanded=\"false\">•••</button>\n    <button type=\"button\" id=\"toggleCopilot\" class=\"control-pill stop-button\" disabled aria-pressed=\"false\"><span class=\"button-symbol\" aria-hidden=\"true\">●</span><span id=\"buttonLabel\">Checking voice…</span></button>\n  </div>\n</nav>\n<div class=\"spatial-hud spatial-hud-jarvis\" id=\"spatialHud\" hidden aria-label=\"Moina visual guide\">\n  <section class=\"spatial-card\">\n    <header class=\"spatial-topbar\">\n      <div class=\"spatial-brand\">\n        <span class=\"brand-mark\" aria-hidden=\"true\">m</span>\n        <span class=\"spatial-brand-copy\"><strong>Moina</strong><small>VISUAL GUIDE</small></span>\n        <span class=\"spatial-live-dot\" aria-hidden=\"true\"></span>\n        <span class=\"spatial-live-label\">LIVE</span>\n      </div>\n      <button type=\"button\" id=\"exitSpatialAr\" class=\"spatial-close\" aria-label=\"Done and return to Co-Pilot\">×</button>\n    </header>\n\n    <div class=\"spatial-focus-stack\">\n      <p id=\"spatialStatus\" role=\"status\" aria-live=\"polite\">Scanning for a surface…</p>\n      <div class=\"spatial-guidance\" id=\"spatialGuidance\" aria-label=\"Current visual instruction\">\n        <span class=\"spatial-guidance-eyebrow\">CURRENT TARGET</span>\n        <strong id=\"spatialTargetLabel\">Ready when you are</strong>\n        <p id=\"spatialTargetInstruction\">Ask Moina what you want to find, then follow the highlighted cue.</p>\n        <small id=\"spatialTargetHint\">Move your phone slowly until the ring sits on the surface you want.</small>\n      </div>\n    </div>\n\n    <div class=\"spatial-bottom-stack\">\n      <div class=\"spatial-step-panel\" id=\"spatialStepPanel\" aria-label=\"Guidance progress\">\n        <div class=\"spatial-step-header\">\n          <strong>YOUR GUIDE</strong>\n          <span id=\"spatialStepProgress\" role=\"status\" aria-live=\"polite\">Ready</span>\n        </div>\n        <div class=\"spatial-progress-track\" id=\"spatialProgressTrack\" hidden role=\"progressbar\" aria-label=\"Walkthrough progress\" aria-valuemin=\"0\" aria-valuemax=\"1\" aria-valuenow=\"0\"></div>\n        <p id=\"spatialStepMessage\">Move the phone until the ring rests on the target. Then tap Place cue.</p>\n        <div class=\"spatial-step-actions\" aria-hidden=\"true\">\n          <button type=\"button\" id=\"spatialStepPrevious\" disabled>Back</button>\n          <button type=\"button\" id=\"spatialStepConfirm\" disabled>Confirm step</button>\n          <button type=\"button\" id=\"spatialStepNext\" disabled>Next</button>\n          <button type=\"button\" id=\"spatialStepFinish\" disabled>Done</button>\n        </div>\n        <small class=\"spatial-step-footnote\">Follow the ring. Moina will show you one step at a time.</small>\n      </div>\n\n      <div class=\"spatial-action-panel\">\n        <span class=\"spatial-action-eyebrow\" id=\"spatialActionEyebrow\">SCANNING FOR A SURFACE</span>\n        <div class=\"spatial-actions\">\n          <button type=\"button\" id=\"placeSpatialAnchor\" disabled>Finding surface…</button>\n        </div>\n        <p id=\"spatialActionHint\" role=\"status\" aria-live=\"polite\">Move your phone slowly. When the ring appears over a surface, Moina will let you place the cue.</p>\n      </div>\n\n      <details class=\"spatial-advanced\" id=\"spatialAdvanced\">\n        <summary>More options</summary>\n        <div class=\"spatial-advanced-content\">\n          <div class=\"spatial-scene-panel\" aria-label=\"Saved spatial scene\">\n            <div class=\"spatial-scene-header\">\n              <strong>SAVED GUIDE</strong>\n              <span id=\"spatialSceneCount\" role=\"status\" aria-live=\"polite\">0 pinned cues</span>\n            </div>\n            <label class=\"spatial-scene-label\" for=\"spatialSceneName\">Save these cues as</label>\n            <input id=\"spatialSceneName\" maxlength=\"60\" autocomplete=\"off\" placeholder=\"e.g. My study desk\" />\n            <div class=\"spatial-scene-actions\">\n              <button type=\"button\" id=\"spatialScenePin\" disabled>Pin current cue</button>\n              <button type=\"button\" id=\"spatialSceneSave\" disabled>Save guide</button>\n            </div>\n            <div class=\"spatial-scene-actions\">\n              <select id=\"spatialSceneSelect\" aria-label=\"Choose a saved guide\">\n                <option value=\"\">No saved guides yet</option>\n              </select>\n              <button type=\"button\" id=\"spatialSceneLoad\" disabled>Load</button>\n              <button type=\"button\" id=\"spatialSceneClear\" disabled>Clear pins</button>\n            </div>\n            <small>Saved guides keep instructions on this device. You'll line the cues up again next time.</small>\n          </div>\n          <div class=\"spatial-aim-panel\" aria-label=\"Fine tune target alignment\">\n            <strong>FINE-TUNE TARGET</strong>\n            <p id=\"spatialAimLabel\" role=\"status\" aria-live=\"polite\">Waiting for a target…</p>\n            <div class=\"spatial-aim-controls\">\n              <button type=\"button\" id=\"spatialAimLeft\" aria-label=\"Nudge target left\" disabled>←</button>\n              <button type=\"button\" id=\"spatialAimUp\" aria-label=\"Nudge target up\" disabled>↑</button>\n              <button type=\"button\" id=\"spatialAimReset\" disabled>Reset</button>\n              <button type=\"button\" id=\"spatialAimDown\" aria-label=\"Nudge target down\" disabled>↓</button>\n              <button type=\"button\" id=\"spatialAimRight\" aria-label=\"Nudge target right\" disabled>→</button>\n            </div>\n            <small>Moina's target is an estimate. Check the ring before placing a cue.</small>\n          </div>\n          <div class=\"spatial-advanced-actions\">\n            <button type=\"button\" id=\"clearSpatialAnchor\" disabled>Clear current cue</button>\n          </div>\n          <p class=\"spatial-note\">After confirmation, the 3D cue card is anchored at the selected hit-test point. This uses screen-region guidance plus your visual confirmation; it does not recognize object geometry or guarantee the chosen surface is the named object. When Co-Pilot is already connected, voice stays live in Spatial AR while camera frames pause; live visual updates resume after you exit AR. If voice setup is incomplete, it may need to end before AR starts.</p>\n        </div>\n      </details>\n      <p class=\"spatial-note spatial-note-short\">The ring is a guide, not object recognition. Check placement before continuing.</p>\n    </div>\n  </section>\n</div>\n<p class=\"privacy-hint\">Camera and microphone start only when you tap Start. Live audio and selected camera frames are processed by Google Cloud Vertex AI; AskMoina does not save raw recordings by default.</p><a class=\"home-link\" href=\"/\">AskMoina</a></section></main></body></html>";

